"use client";

import { Link, RichTextEditor } from "@/components/editor";
import { Placeholder } from "@tiptap/extension-placeholder";
import { useEditor } from "@tiptap/react";
import { SendIcon, Trash2Icon } from "lucide-react";
import { Suspense, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { Toolbar } from "./toolbar";
import type { EmailComposerProps } from "./types";
import { FIELD, LABEL, ROW, STARTER_KIT } from "./utils";

import "@/components/editor/style.css";

const EmailComposerInner = ({
  className,
  initialContent,
  initialSubject = "",
  initialTo = "",
  onDiscard,
  onSend,
  placeholder = "Write your message…",
  title = "New message",
}: EmailComposerProps) => {
  const id = useId();
  const form = useRef<HTMLFormElement>(null);
  const [to, setTo] = useState(initialTo);
  const [subject, setSubject] = useState(initialSubject);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState(false);
  const [isEmpty, setIsEmpty] = useState(true);

  const editor = useEditor({
    content: initialContent ?? "",
    editorProps: {
      handleKeyDown: (_, event) => {
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          form.current?.requestSubmit();
          return true;
        }
        return false;
      },
    },
    extensions: [STARTER_KIT, Link, Placeholder.configure({ placeholder })],
    immediatelyRender: false,
    onCreate: ({ editor: e }) => setIsEmpty(e.isEmpty),
    onUpdate: ({ editor: e }) => setIsEmpty(e.isEmpty),
    shouldRerenderOnTransaction: false,
  });

  const canSend = to.trim() !== "" && !isEmpty && !sending;

  const reset = () => {
    setTo(initialTo);
    setSubject(initialSubject);
    setError(false);
    if (editor && !editor.isDestroyed) {
      editor.commands.setContent(initialContent ?? "");
      setIsEmpty(editor.isEmpty);
    }
  };

  const send = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!editor || editor.isDestroyed || !canSend) {
      return;
    }
    setSending(true);
    setError(false);
    try {
      await onSend?.({
        // ProseMirror keeps attrs in null-prototype objects, which React
        // can't send to a server action. structuredClone makes them plain.
        content: structuredClone(editor.getJSON()),
        subject: subject.trim(),
        to: to.trim(),
      });
    } catch {
      setError(true);
      return;
    } finally {
      setSending(false);
    }
    reset();
  };

  const discard = () => {
    reset();
    onDiscard?.();
  };

  return (
    <form
      ref={form}
      aria-labelledby={`${id}-title`}
      className={cn(
        "border-border/60 bg-muted/50 flex flex-col overflow-hidden rounded-xl border p-1",
        className
      )}
      onSubmit={send}
    >
      <header className="flex min-h-9 shrink-0 items-center justify-between gap-2 px-2.5 pb-1">
        <h3 className="text-sm font-semibold" id={`${id}-title`}>
          {title}
        </h3>
        {error && (
          <p
            className="rounded-full bg-rose-500/10 px-2 py-0.5 text-xs font-medium text-rose-700 dark:text-rose-400"
            role="alert"
          >
            Couldn’t send. Try again.
          </p>
        )}
      </header>
      <RichTextEditor
        className="flex min-h-0 flex-1 flex-col rounded-none! border-0! bg-transparent!"
        editable={!sending}
        editor={editor}
        variant="compact"
      >
        <div className="border-border/60 bg-card flex min-h-0 flex-1 flex-col overflow-hidden rounded-lg border">
          <div className={ROW}>
            <label className={LABEL} htmlFor={`${id}-to`}>
              To
            </label>
            <input
              autoComplete="email"
              className={FIELD}
              disabled={sending}
              id={`${id}-to`}
              inputMode="email"
              multiple
              name="to"
              onChange={(event) => setTo(event.target.value)}
              placeholder="name@example.com"
              type="email"
              value={to}
            />
          </div>
          <div className={ROW}>
            <label className={LABEL} htmlFor={`${id}-subject`}>
              Subject
            </label>
            <input
              className={FIELD}
              disabled={sending}
              id={`${id}-subject`}
              name="subject"
              onChange={(event) => setSubject(event.target.value)}
              type="text"
              value={subject}
            />
          </div>
          <div
            className="min-h-0 flex-1 cursor-text overflow-y-auto"
            onMouseDown={(event) => {
              if (event.target === event.currentTarget) {
                event.preventDefault();
                editor?.commands.focus("end");
              }
            }}
          >
            <RichTextEditor.Content className="[&_.ProseMirror]:min-h-48! [&_.ProseMirror]:px-4! [&_.ProseMirror]:py-3! [&_.ProseMirror]:text-base [&_.ProseMirror]:leading-relaxed sm:[&_.ProseMirror]:text-sm" />
          </div>
        </div>
        {/* The footer is the container (not the form) so the composer keeps its
            own width inside shrink-to-fit parents like dialogs and popovers. */}
        <footer className="@container flex shrink-0 items-center gap-2 px-0.5 pt-1">
          <Toolbar />
          <div className="ml-auto flex items-center gap-1.5">
            <Button
              aria-label="Discard"
              className="text-muted-foreground hover:text-foreground rounded-md"
              disabled={sending}
              onClick={discard}
              size="icon-sm"
              title="Discard"
              type="button"
              variant="ghost"
            >
              <Trash2Icon />
            </Button>
            <Button
              aria-keyshortcuts="Control+Enter Meta+Enter"
              className="rounded-lg"
              disabled={!canSend}
              size="sm"
              type="submit"
            >
              <SendIcon />
              <span className="sr-only @[22rem]:not-sr-only">
                {sending ? "Sending…" : "Send"}
              </span>
            </Button>
          </div>
        </footer>
      </RichTextEditor>
    </form>
  );
};

// Tiptap's useEditor reads Math.random(), which Next.js `cacheComponents`
// rejects during prerender unless the component sits under a Suspense boundary.
export const EmailComposer = (props: EmailComposerProps) => (
  <Suspense fallback={null}>
    <EmailComposerInner {...props} />
  </Suspense>
);

export type { EmailComposerProps, EmailMessage } from "./types";

"use client";

import { RichTextEditor } from "@/components/editor";

// Quiet ghost buttons on the gray footer: size-8 squares, size-4 icons, and a
// plain white fill for hover and the active format instead of a tinted ring.
const BUTTONS = [
  "[&_.rte-controls-group>button]:size-8!",
  "[&_.rte-controls-group>button]:rounded-md!",
  "[&_.rte-controls-group>button:hover]:bg-background!",
  "[&_.rte-controls-group>button[aria-pressed=true]]:bg-background!",
  "[&_.rte-controls-group>button[aria-pressed=true]]:text-foreground!",
  "[&_.rte-controls-group>button[aria-pressed=true]]:shadow-none!",
  "[&_.rte-controls-group>button[data-state=on]]:bg-background!",
  "[&_.rte-controls-group>button[data-state=on]]:text-foreground!",
  "[&_.rte-controls-group>button[data-state=on]]:shadow-none!",
  "[&_.rte-editor-icon]:size-4!",
].join(" ");

export const Toolbar = () => (
  <div className={`flex min-w-0 items-center ${BUTTONS}`}>
    <RichTextEditor.ControlsGroup>
      <RichTextEditor.Bold />
      <RichTextEditor.Italic />
      <RichTextEditor.Underline />
      <RichTextEditor.Link />
    </RichTextEditor.ControlsGroup>
    <RichTextEditor.ControlsGroup>
      <RichTextEditor.BulletList />
      <RichTextEditor.OrderedList />
    </RichTextEditor.ControlsGroup>
  </div>
);

import type { JSONContent } from "@tiptap/core";

export interface EmailMessage {
  content: JSONContent;
  subject: string;
  to: string;
}

export interface EmailComposerProps {
  className?: string;
  initialContent?: JSONContent;
  initialSubject?: string;
  initialTo?: string;
  onDiscard?: () => void;
  onSend?: (message: EmailMessage) => Promise<void> | void;
  placeholder?: string;
  title?: string;
}

import { Link } from "@tiptap/extension-link";
import { StarterKit } from "@tiptap/starter-kit";

export const STARTER_KIT = StarterKit.configure({
  blockquote: false,
  code: false,
  codeBlock: false,
  heading: false,
  horizontalRule: false,
  link: false,
  strike: false,
  trailingNode: false,
});

// Server-safe: pass these to generateHTML() to turn the body into email HTML.
export const EMAIL_EXTENSIONS = [
  STARTER_KIT,
  Link.configure({ openOnClick: false }),
];

export const ROW =
  "border-border/60 flex shrink-0 items-center gap-3 border-b px-4";

export const LABEL = "text-muted-foreground w-14 shrink-0 text-sm";

export const FIELD =
  "placeholder:text-muted-foreground/70 h-10 min-w-0 flex-1 bg-transparent text-base outline-none disabled:opacity-50 sm:text-sm";
